 start_secure_session();require_once '../config/database.php';if(($_SESSION['role']??'')!=='assistant'){header('Location: ../auth/login.php');exit;} $msg='';if($_SERVER['REQUEST_METHOD']==='POST'){ $pid=(int)($_POST['patient_id']??0);$proc=trim($_POST['procedure_name']??'');$diag=trim($_POST['diagnosis']??'');$notes=trim($_POST['notes']??'');if($pid&&$proc){$st=$conn->prepare("INSERT INTO dental_records(patient_id,record_date,procedure_name,diagnosis,dentist_name,notes) VALUES(?,CURDATE(),?,?,?,?)");$name=($_SESSION['first_name']??'').' '.($_SESSION['last_name']??'').' (Assistant)';$st->bind_param('issss',$pid,$proc,$diag,$name,$notes);$st->execute();$st->close();$msg='Dental chart entry saved.';log_activity($conn,$_SESSION['user_id'],'Created dental chart entry','Dental Chart','Patient ID '.$pid);}}$patients=$conn->query("SELECT id,first_name,last_name FROM users WHERE role='patient' AND status='active' ORDER BY last_name,first_name");require '../includes/ui.php';ui_header('Dental Charts','assistant');ui_sidebar('assistant','dental_chart.php');?><div class="page-head"><div><div class="eyebrow">DENTAL CHARTING</div><h1>Create Dental Chart Entry</h1><div class="muted">Record a procedure or finding for a patient.</div></div></div><?php if($msg)flash('success',$msg);?><section class="card"><form method="post" class="form-grid"><div class="field full"><label>Patient *</label><select name="patient_id" required><option value="">Select patient</option><?php while($p=$patients->fetch_assoc()):?><option value="<?=$p['id']?>"><?=e($p['last_name'].', '.$p['first_name'])?></option><?php endwhile;?></select></div><div class="field"><label>Procedure *</label><input name="procedure_name" required></div><div class="field"><label>Diagnosis / Finding</label><input name="diagnosis"></div><div class="field full"><label>Remarks</label><textarea name="notes"></textarea></div><div class="actions full"><button class="btn btn-primary">Save Chart Entry</button></div></form></section><?php ui_footer();?>
